import './App.css';
import { useEffect, useState } from 'react';
import { logoutUser } from './api';
import Dashboard from './dashboard';
import Login from './login';
import Logout from './logout';
import Register from './register';

const pagePaths = {
  Dashboard: '/dashboard',
  'My Work': '/my-work',
  'My Tasks': '/my-tasks',
  'My Files': '/my-files',
  'My Calendar': '/my-calendar',
  'My Leads': '/my-leads',
  Projects: '/projects',
  Admin: '/admin',
  Settings: '/settings',
};

function pageFromPath(pathname) {
  return Object.keys(pagePaths).find((page) => pagePaths[page] === pathname) || 'Dashboard';
}

function App() {
  const [showRegister, setShowRegister] = useState(false);
  const [showLogout, setShowLogout] = useState(false);
  const [activePage, setActivePage] = useState(() => pageFromPath(window.location.pathname));
  const [currentUser, setCurrentUser] = useState(() => {
    const savedSession = localStorage.getItem('taskManagerSession');
    if (!savedSession) return null;
    const session = JSON.parse(savedSession);
    return { fullname: session.userName, role: session.userRole };
  });

  useEffect(() => {
    function handleHistoryChange() {
      setActivePage(pageFromPath(window.location.pathname));
    }
    window.addEventListener('popstate', handleHistoryChange);
    return () => window.removeEventListener('popstate', handleHistoryChange);
  }, []);

  function navigateTo(page) {
    const path = pagePaths[page] || pagePaths.Dashboard;
    window.history.pushState({}, '', path);
    setActivePage(page);
  }

  function handleLogin(user, rememberMe = false) {
    const name = user.fullname || user.username || 'there';
    setCurrentUser(user);

    if (rememberMe) {
      localStorage.setItem('taskManagerSession', JSON.stringify({ userName: name, userRole: user.role || 'User' }));
    } else {
      localStorage.removeItem('taskManagerSession');
    }
  }

  async function handleLogout() {
    try {
      await logoutUser();
    } catch (error) {
      // Clear the local session even if the server is unavailable.
    }
    localStorage.removeItem('taskManagerSession');
    setCurrentUser(null);
    setShowLogout(true);
  }

  if (showLogout) {
    return <Logout onLogin={() => setShowLogout(false)} />;
  }

  if (currentUser) {
    return <Dashboard user={currentUser} userName={currentUser.fullname || currentUser.username || 'there'} userRole={currentUser.role || 'User'} activePage={activePage} onNavigate={navigateTo} onLogout={handleLogout} />;
  }

  return (
    showRegister
      ? <Register onLogin={() => setShowRegister(false)} onSuccess={handleLogin} />
      : <Login onRegister={() => setShowRegister(true)} onSuccess={handleLogin} />
  );
}

export default App;
